// Node.js start-up (loaded by src/instrumentation.ts): on the cPanel host there is no Prisma CLI, so create any missing tables
// from prisma/schema.sql (idempotent CREATE … IF NOT EXISTS, generated by scripts/schema-sql.mjs) before the first request.
import { mkdir, readFile } from "node:fs/promises";
import path from "node:path";
import { db } from "@/lib/db";

export async function prepareDatabase() {
  const url = process.env.DATABASE_URL;
  if (!url) return;
  try {
    // SQLite creates the file but not its folder (e.g. file:/home/user/gbpninja-data/app.db).
    const file = url.startsWith("file:") ? url.slice(5) : null;
    if (file && path.isAbsolute(file)) await mkdir(path.dirname(file), { recursive: true });
    const sql = await readFile(path.join(process.cwd(), "prisma", "schema.sql"), "utf8");
    const statements = sql
      .split(/;\s*$/m)
      .map((s) => s.replace(/^--.*$/gm, "").trim())
      .filter(Boolean);
    for (const s of statements) await db.$executeRawUnsafe(s);
  } catch (e) {
    console.error("[db] Could not prepare the database:", e);
  }
}
